CREATE OR REPLACE FUNCTION public.reserve_report_shot(p_player text, p_report bigint, p_mime text, p_bytes integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  cfg jsonb := (select value from balance where key = 'report_shots');
  ext text := case p_mime when 'image/webp' then 'webp' when 'image/png' then 'png' when 'image/jpeg' then 'jpg' end;
  used int;
  next_n int;
  new_id bigint;
